"""AI_YEREL_GK - app.py (GB/IST 1)"""
import os, sys, time, json, atexit, base64, io, re, subprocess, importlib.util, threading
from datetime import datetime
from pathlib import Path

from flask import Flask, request, jsonify, send_from_directory, send_file, Response
from flask_cors import CORS
from dotenv import load_dotenv

BASE_DIR = Path(__file__).resolve().parent
load_dotenv(BASE_DIR / ".env")
os.environ.setdefault("OLLAMA_IGPU_ENABLE", "1")

app = Flask(__name__, static_folder=str(BASE_DIR / "static"))
CORS(app, expose_headers=["X-Saved-Filename"])

EXCELS_DIR = BASE_DIR / "excels"
UPLOADS_DIR = BASE_DIR / "uploads"
CHARTS_DIR = BASE_DIR / "static" / "charts"
CONFIG_DIR = BASE_DIR / "config"
SKILLS_DIR = BASE_DIR / "skills"
for d in (EXCELS_DIR, UPLOADS_DIR, CHARTS_DIR, CONFIG_DIR, SKILLS_DIR):
    d.mkdir(parents=True, exist_ok=True)

MODEL_CTX = {
    "qwen2.5:7b": 8192, "qwen2.5-coder:7b": 12288, "gemma4:latest": 8192,
    "llama3.1:latest": 8192, "deepseek-r1:7b": 4096, "qwen2.5:3b": 4096,
    "llama3.2:3b": 4096, "gemma2:2b": 4096, "deepseek-r1:1.5b": 4096,
    "moondream:latest": 2048, "granite3.2-vision:2b": 2048,
}
DEFAULT_CTX = 4096
CODE_KW = ("python", "kod", "script", "fonksiyon", "html", "css", "javascript", "bug", "flask", "yazilim", "class ", "def ")
REASON_KW = ("neden", "kanitla", "adim adim", "mantik", "karsilastir", "analiz et", "hesapla", "ispat")
WEB_KW = ("guncel", "arastir", "webde ara", "haberler", "fiyat", "bugun", "doviz", "kur", "borsa", "usd", "euro", "piyasa", "temmuz", "2025", "2026", "sud", "tl ")

def get_num_ctx(model: str) -> int:
    if model in MODEL_CTX: return MODEL_CTX[model]
    m = (model or "").lower()
    if "coder" in m: return 12288
    if "deepseek-r1" in m and ("7b" in m or "8b" in m): return 4096
    if any(x in m for x in ("1.5b", "2b", "3b")): return 4096
    if "vision" in m or "moondream" in m: return 2048
    return DEFAULT_CTX

def resolve_auto_model(prompt: str, has_images=False):
    """Returns (model_name, reason_label)"""
    p = (prompt or "").lower()
    if has_images or any(k in p for k in ("gorsel", "resim", "fotograf", "tabloyu oku")):
        return "moondream:latest", "gorsel"
    if any(k in p for k in WEB_KW):
        if os.environ.get("GEMINI_API_KEY", "").strip():
            return "gemini-2.5-flash", "web-ajan"
        return "qwen2.5:7b", "web-yerel"
    if any(k in p for k in CODE_KW):
        return "qwen2.5-coder:7b", "kod"
    if any(k in p for k in REASON_KW):
        return "deepseek-r1:7b", "muhakeme"
    return "qwen2.5:7b", "genel"

def discover_skills():
    skills = {}
    if not SKILLS_DIR.is_dir(): return skills
    for entry in sorted(os.listdir(SKILLS_DIR)):
        sp = SKILLS_DIR / entry
        if not sp.is_dir(): continue
        py_files = [f for f in os.listdir(sp) if f.endswith(".py")]
        if not py_files: continue
        chosen = (entry + ".py") if (entry + ".py") in py_files else py_files[0]
        try:
            spec = importlib.util.spec_from_file_location(f"skills_{entry}", str(sp / chosen))
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            if hasattr(mod, "run_skill") and hasattr(mod, "SKILL_INFO"):
                skills[entry] = {"info": mod.SKILL_INFO, "run_skill": mod.run_skill}
        except Exception as e:
            print(f"[Skill] {entry}: {e}")
    return skills

SKILLS = discover_skills()

OLLAMA_HOST = "http://127.0.0.1:11434"
ollama_client = ollama_status_client = None
try:
    import ollama
    ollama_client = ollama.Client(host=OLLAMA_HOST, timeout=300)
    ollama_status_client = ollama.Client(host=OLLAMA_HOST, timeout=8)
except Exception as e:
    print(f"[ollama] {e}")

def is_ollama_running():
    if not ollama_status_client: return False
    try:
        ollama_status_client.list(); return True
    except Exception: return False

def start_ollama():
    if is_ollama_running(): return
    try:
        flags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
        subprocess.Popen(["ollama", "serve"], creationflags=flags, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        for _ in range(20):
            time.sleep(0.5)
            if is_ollama_running():
                print("[Ollama] OK"); return
    except Exception as e:
        print(f"[Ollama] {e}")

def stop_ollama():
    try:
        if sys.platform == "win32":
            os.system("taskkill /F /IM ollama.exe /T >nul 2>&1")
            os.system("taskkill /F /IM ollama_llama_server.exe /T >nul 2>&1")
    except Exception: pass

atexit.register(stop_ollama)

GEMINI_KEY = os.environ.get("GEMINI_API_KEY", "").strip()
gemini_client = None
if GEMINI_KEY:
    try:
        from google import genai
        gemini_client = genai.Client(api_key=GEMINI_KEY)
        print("[Gemini] OK")
    except Exception as e:
        print(f"[Gemini] {e}")

def is_cloud(model):
    return (model or "").startswith("gemini")

STATS_FILE = BASE_DIR / "model_stats.json"
_stats_lock = threading.Lock()

def record_time(model, seconds):
    with _stats_lock:
        stats = {}
        if STATS_FILE.exists():
            try: stats = json.loads(STATS_FILE.read_text(encoding="utf-8"))
            except Exception: pass
        e = stats.get(model, {"count": 0, "avg_seconds": 0.0})
        c = e["count"] + 1
        avg = (e["avg_seconds"] * e["count"] + seconds) / c
        stats[model] = {"count": c, "avg_seconds": round(avg, 2)}
        try: STATS_FILE.write_text(json.dumps(stats, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception: pass

def build_system_prompt(model=None, role="default"):
    today = datetime.now().strftime("%d.%m.%Y")
    master = "Sen yerel AI asistansin. TURKCE yaz. Kisa ve net ol."
    role_extra = ""
    pf = CONFIG_DIR / "prompts.json"
    if pf.exists():
        try:
            data = json.loads(pf.read_text(encoding="utf-8"))
            master = data.get("master_system_prompt", master)
            roles = data.get("roles") or {}
            role_extra = roles.get(role) or roles.get("default") or ""
        except Exception: pass
    return f"{master}\n{role_extra}\nBugunun tarihi: {today}."

def list_local_models():
    try:
        if ollama_status_client:
            return [m.model for m in ollama_status_client.list().models]
    except Exception: pass
    return ["qwen2.5:7b", "qwen2.5:3b", "moondream:latest", "gemma4:latest"]

def _stream_ollama(model, prompt, history=None, images=None, role="default"):
    if not ollama_client:
        yield "Ollama yok."; return
    messages = [{"role": "system", "content": build_system_prompt(model, role)}]
    for h in history or []:
        if h.get("role") in ("user", "assistant"):
            messages.append({"role": h["role"], "content": h.get("content", "")})
    cur = {"role": "user", "content": prompt}
    if images: cur["images"] = images
    messages.append(cur)
    if not is_ollama_running(): start_ollama()
    try:
        stream = ollama_client.chat(model=model, messages=messages, keep_alive="30m",
                                    options={"num_ctx": get_num_ctx(model)}, stream=True)
        for chunk in stream:
            piece = chunk.get("message", {}).get("content", "")
            if piece: yield piece
    except Exception as e:
        yield f"\n[Hata] {e}"

def _stream_gemini(model, prompt, history=None, role="default", use_search=False):
    if not gemini_client:
        yield "Gemini yok / API anahtari eksik."; return
    try:
        from google.genai import types
        contents = []
        for h in history or []:
            role_g = "user" if h.get("role") == "user" else "model"
            if h.get("content"):
                contents.append(types.Content(role=role_g, parts=[types.Part.from_text(text=h["content"])]))
        contents.append(types.Content(role="user", parts=[types.Part.from_text(text=prompt)]))
        kwargs = {"system_instruction": build_system_prompt(model, role)}
        if use_search:
            try:
                kwargs["tools"] = [types.Tool(google_search=types.GoogleSearch())]
            except Exception:
                pass
        cfg = types.GenerateContentConfig(**kwargs)
        for chunk in gemini_client.models.generate_content_stream(model="gemini-2.5-flash", contents=contents, config=cfg):
            if getattr(chunk, "text", None): yield chunk.text
    except Exception as e:
        yield f"\n[Gemini Hata] {e}"

def execute_chart_code(text):
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        m = re.search(r"```python(.*?)```", text, re.DOTALL)
        if not m or ("plt." not in m.group(1) and "matplotlib" not in m.group(1)):
            return None
        code = m.group(1)
        fn = f"chart_{int(time.time())}.png"
        path = CHARTS_DIR / fn
        code = code.replace("plt.show()", f"plt.savefig(r'{path}', bbox_inches='tight')")
        if "plt.savefig" not in code:
            code += f"\nplt.savefig(r'{path}', bbox_inches='tight')"
        plt.figure()
        exec(code, {})
        plt.close("all")
        return f"/static/charts/{fn}"
    except Exception as e:
        print(f"[chart] {e}")
        return None

def stream_chat_response(prompt, model, history=None, images=None, role="default"):
    def event_stream():
        route_label = None
        model_use = model
        if model == "auto":
            model_use, route_label = resolve_auto_model(prompt, has_images=bool(images))
        # Web keywords even if not auto: prefer Gemini when key exists
        pl = (prompt or "").lower()
        if any(k in pl for k in WEB_KW) and gemini_client and not is_cloud(model_use) and model in ("auto", "qwen2.5:7b", "gemma4:latest"):
            model_use, route_label = "gemini-2.5-flash", "web-ajan"

        if model_use.startswith("skill:"):
            key = model_use[6:]
            sk = SKILLS.get(key)
            if not sk:
                yield json.dumps({"type": "error", "message": f"Skill yok: {key}"}, ensure_ascii=False) + "\n"
                return
            yield json.dumps({"type": "meta", "model": model_use, "route": "skill"}, ensure_ascii=False) + "\n"
            try:
                def runner(p):
                    return "".join(_stream_ollama("qwen2.5:7b", p, role=role))
                result = sk["run_skill"](runner)
                yield json.dumps({"type": "chunk", "text": str(result)}, ensure_ascii=False) + "\n"
            except Exception as e:
                yield json.dumps({"type": "error", "message": str(e)}, ensure_ascii=False) + "\n"
            yield json.dumps({"type": "done"}, ensure_ascii=False) + "\n"
            return

        meta = {"type": "meta", "model": model_use}
        if route_label:
            meta["route"] = route_label
        yield json.dumps(meta, ensure_ascii=False) + "\n"

        t0 = time.time()
        acc = []
        use_search = (route_label == "web-ajan") or any(k in pl for k in WEB_KW)
        try:
            if is_cloud(model_use):
                gen = _stream_gemini(model_use, prompt, history, role, use_search=use_search)
            else:
                gen = _stream_ollama(model_use, prompt, history, images, role)
            for piece in gen:
                acc.append(piece)
                yield json.dumps({"type": "chunk", "text": piece}, ensure_ascii=False) + "\n"
            full = "".join(acc)
            chart = execute_chart_code(full)
            if chart:
                yield json.dumps({"type": "chunk", "text": f"\n\n![Grafik]({chart})"}, ensure_ascii=False) + "\n"
            record_time(model_use, time.time() - t0)
            yield json.dumps({"type": "done"}, ensure_ascii=False) + "\n"
        except Exception as e:
            yield json.dumps({"type": "error", "message": str(e)}, ensure_ascii=False) + "\n"
    return Response(event_stream(), mimetype="application/x-ndjson")

@app.route("/")
def index():
    return send_from_directory(app.static_folder, "index.html")

@app.route("/chat", methods=["POST"])
def chat():
    data = request.get_json(silent=True) or {}
    prompt = (data.get("prompt") or "").strip()
    model = data.get("model") or "qwen2.5:7b"
    history = data.get("history") or []
    role = data.get("role") or "default"
    if not prompt: return jsonify({"error": "Bos mesaj"}), 400
    return stream_chat_response(prompt, model, history, role=role)

@app.route("/chat-multi-image", methods=["POST"])
def chat_multi_image():
    data = request.get_json(silent=True) or {}
    prompt = (data.get("prompt") or "").strip() or "Bu gorselleri acikla."
    model = data.get("model") or "moondream:latest"
    images = data.get("images") or []
    history = data.get("history") or []
    role = data.get("role") or "default"
    if not images: return jsonify({"error": "Gorsel yok"}), 400
    return stream_chat_response(prompt, model, history, images, role)

@app.route("/upload-pdf", methods=["POST"])
def upload_pdf():
    try:
        from pypdf import PdfReader
        f = request.files.get("file")
        if not f: return jsonify({"error": "Dosya yok"}), 400
        reader = PdfReader(io.BytesIO(f.read()))
        text = "\n".join([(p.extract_text() or "") for p in reader.pages]).strip()
        return jsonify({"text": text, "pages": len(reader.pages)})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/image-to-excel", methods=["POST"])
def image_to_excel():
    data = request.get_json(silent=True) or {}
    image_b64 = data.get("image")
    model = data.get("model") or "moondream:latest"
    if not image_b64: return jsonify({"error": "Gorsel yok"}), 400
    try:
        if not ollama_client: return jsonify({"error": "Ollama yok"}), 500
        if not is_ollama_running(): start_ollama()
        res = ollama_client.chat(model=model, messages=[{
            "role": "user", "content": "Bu gorseldeki tabloyu | ile ayirarak yaz.", "images": [image_b64]
        }], options={"num_ctx": get_num_ctx(model)})
        result_text = res["message"]["content"]
        from openpyxl import Workbook
        wb = Workbook(); ws = wb.active
        for line in result_text.strip().splitlines():
            if line.strip():
                ws.append([c.strip() for c in line.strip("|").split("|")])
        buf = io.BytesIO(); wb.save(buf); buf.seek(0)
        return send_file(buf, as_attachment=True, download_name="tablo.xlsx",
                         mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
    except Exception as e:
        return jsonify({"error": str(e)}), 500

CONV_FILE = BASE_DIR / "conversations_backup.json"

@app.route("/save-conversations", methods=["POST"])
def save_conversations():
    data = request.get_json(silent=True)
    if data is None: return jsonify({"error": "Gecersiz"}), 400
    try:
        CONV_FILE.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")
        return jsonify({"status": "ok"})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route("/load-conversations", methods=["GET"])
def load_conversations():
    if not CONV_FILE.exists(): return jsonify({"found": False})
    try:
        return jsonify({"found": True, "data": json.loads(CONV_FILE.read_text(encoding="utf-8"))})
    except Exception as e:
        return jsonify({"found": False, "error": str(e)})

@app.route("/status", methods=["GET"])
def status():
    igpu = os.environ.get("OLLAMA_IGPU_ENABLE", "0") in ("1", "true", "True")
    return jsonify({
        "ollama": is_ollama_running(),
        "gemini": bool(gemini_client),
        "gpu": igpu and is_ollama_running(),
        "igpu_flag": igpu
    })

@app.route("/model-stats", methods=["GET"])
def model_stats():
    if STATS_FILE.exists():
        try: return jsonify(json.loads(STATS_FILE.read_text(encoding="utf-8")))
        except Exception: pass
    return jsonify({})

@app.route("/models", methods=["GET"])
def list_models():
    local = list_local_models()
    clouds = ["gemini-2.5-flash"] if gemini_client else []
    skills = [{"key": f"skill:{k}", "name": v["info"].get("name", k), "description": v["info"].get("description", "")} for k, v in SKILLS.items()]
    return jsonify({"local": ["auto"] + local, "cloud": clouds, "research": [], "skills": skills})

@app.route("/warmup", methods=["POST"])
def warmup():
    return jsonify({"status": "ok"})

@app.route("/shutdown", methods=["POST"])
def shutdown():
    stop_ollama()
    func = request.environ.get("werkzeug.server.shutdown")
    if func: func()
    return jsonify({"status": "kapatiliyor"})

if __name__ == "__main__":
    print("=" * 50)
    print("  AI_YEREL_GRK | GB/IST 1")
    print("=" * 50)
    start_ollama()
    app.run(host="127.0.0.1", port=5000, debug=False, use_reloader=False, threaded=True)
