function save(){
  localStorage.setItem('grk_convs',JSON.stringify(conversations));
  localStorage.setItem('grk_current',currentId); localStorage.setItem('grk_next',nextId);
  fetch('/save-conversations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({conversations,currentConvId:currentId,nextId})}).catch(()=>{});
}
