  try{ conversations=JSON.parse(localStorage.getItem('grk_convs')||'{}'); currentId=localStorage.getItem('grk_current'); nextId=parseInt(localStorage.getItem('grk_next')||'1'); }catch{conversations={};}
  if(!currentId||!conversations[currentId]){
    try{ const d=await(await fetch('/load-conversations')).json(); if(d.found&&d.data&&d.data.conversations){ conversations=d.data.conversations; currentId=d.data.currentConvId; nextId=d.data.nextId||1; } }catch{}
  }
  if(!currentId||!conversations[currentId]) createNewChat(); else { renderHistory(); renderChat(); updateTopBadge(conversations[currentId]); }
}

function welcome(){ return '<strong>Hos geldin</strong>Model auto iken web/fiyat/kur istekleri Gemini web-ajana gidebilir. Sol listede en yeni usttedir.'; }

function createNewChat(){
  const model=modelSelect.value||'auto';
  const id=String(nextId++);
  conversations[id]={title:'Yeni Sohbet',model,created:Date.now(),messages:[{role:'system',content:'WELCOME'}],pending:false};
  currentId=id; save(); renderHistory(); renderChat(); updateTopBadge(conversations[id]);
}

function deleteChat(id){
  if(!confirm('Silinsin mi?')) return;
  delete conversations[id];
  if(currentId===id){ const ids=Object.keys(conversations); currentId=ids[0]||null; }
  save(); if(!currentId) createNewChat(); else { renderHistory(); renderChat(); updateTopBadge(conversations[currentId]); }
}

function renderHistory(){
  historyList.innerHTML='';
  const ids=Object.keys(conversations).sort((a,b)=>{
    const ca=conversations[a].created||0, cb=conversations[b].created||0;
    if(cb!==ca) return cb-ca;
    return parseInt(b)-parseInt(a);
  });
  ids.forEach(id=>{
    const c=conversations[id];
    const div=document.createElement('div');
    div.className='hist-item'+(id===currentId?' active':'')+(c.pending?' pending':'')+(c.blink?' blink-done':'');
    const t=document.createElement('span'); t.className='title';
    t.innerHTML=(c.pending?'<span class="hourglass">â³</span>':'')+(c.title||c.model);
    const tag=document.createElement('span');
    const route=c.lastRoute;
    if(route){ tag.className='tag tag-route'; tag.textContent=route; }
    else { tag.className='tag '+tagCls(kind(c.lastUsedModel||c.model)); tag.textContent=kind(c.lastUsedModel||c.model); }
    const del=document.createElement('button'); del.className='del'; del.textContent='x'; del.onclick=e=>{ e.stopPropagation(); deleteChat(id); };
    div.appendChild(t); div.appendChild(tag); div.appendChild(del);
    div.onclick=()=>{ currentId=id; if(conversations[id]) conversations[id].blink=false; save(); renderHistory(); renderChat(); updateTopBadge(conversations[id]); };
    historyList.appendChild(div);
  });
}

function attachMini(wrap, text){
  const row=document.createElement('div'); row.className='msg-actions';
  const c=document.createElement('button'); c.className='msg-action-btn'; c.textContent='Kopyala'; c.onclick=()=>navigator.clipboard.writeText(text);
