  row.appendChild(c); row.appendChild(d); wrap.appendChild(row);
}

function renderChat(){
  const conv=conversations[currentId]; if(!conv) return;
  chatBox.innerHTML=''; chatTitle.textContent=conv.title||'Sohbet'; updateTopBadge(conv);
  (conv.messages||[]).forEach(m=>{
    const wrap=document.createElement('div'); wrap.className='msg-wrapper '+(m.role||'assistant');
    if(m.role==='assistant'){
      const b=document.createElement('div');
      let label=m.model||conv.model;
      if(m.route) label += ' Â· '+m.route;
      b.className='badge '+(m.route?'badge-route':badgeCls(kind(m.model||conv.model)));
      b.textContent=label; wrap.appendChild(b);
    }
    const msg=document.createElement('div'); msg.className='msg';
    if(m.role==='system'&&m.content==='WELCOME') msg.innerHTML=welcome(); else msg.textContent=m.content;
    wrap.appendChild(msg);
    if(m.role==='assistant'&&m.content) attachMini(wrap,m.content);
    chatBox.appendChild(wrap);
  });
  chatBox.scrollTop=chatBox.scrollHeight;
}

function toBase64(file){ return new Promise((res,rej)=>{ const r=new FileReader(); r.onload=()=>res(r.result.split(',')[1]); r.onerror=rej; r.readAsDataURL(file); }); }

document.getElementById('selectImageBtn').onclick=()=>document.getElementById('imageInput').click();
document.getElementById('imageInput').onchange=async e=>{
  for(const f of Array.from(e.target.files||[])){
