async function sendMessage(){
  const conv=conversations[currentId]; if(!conv||pending) return;
  const text=promptEl.value.trim(); if(!text&&!currentImages.length) return;
  conv.messages=(conv.messages||[]).filter(m=>!(m.role==='system'&&m.content==='WELCOME'));
  const imgs=currentImages.slice();
  let userMsg=text||('Gorsel hakkinda yorum');
  conv.messages.push({role:'user',content:userMsg+(imgs.length?' ['+imgs.length+' gorsel]':'')});
  if(conv.messages.filter(m=>m.role==='user').length===1) conv.title=userMsg.length>28?userMsg.slice(0,28)+'...':userMsg;
  if(!conv.created) conv.created=Date.now();
  promptEl.value=''; currentImages=[]; imagePreview.innerHTML=''; imagePreview.style.display='none';
  pending=true; conv.pending=true; sendBtn.disabled=true; stopBtn.style.display='inline-block'; sendBtn.textContent='...';
  save(); renderChat(); renderHistory();
  const history=conv.messages.filter(m=>m.role==='user'||m.role==='assistant').slice(0,-1).slice(-20).map(m=>({role:m.role,content:m.content}));
  abortCtrl=new AbortController();
  try{
    const hasImg=imgs.length>0;
    const res=await fetch(hasImg?'/chat-multi-image':'/chat',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({prompt:userMsg,model:conv.model,history,images:hasImg?imgs:undefined,role:roleSelect.value||'default'}), signal:abortCtrl.signal});
    if(!res.ok||!res.body) throw new Error('Sunucu');
    const reader=res.body.getReader(); const dec=new TextDecoder(); let buf='', acc='', used=conv.model, route=null;
    const wrap=document.createElement('div'); wrap.className='msg-wrapper assistant';
    const badge=document.createElement('div'); badge.className='badge '+badgeCls(kind(used)); badge.textContent=used; wrap.appendChild(badge);
    const msgDiv=document.createElement('div'); msgDiv.className='msg'; msgDiv.innerHTML='<span class="blink">...</span>'; wrap.appendChild(msgDiv); chatBox.appendChild(wrap);
    while(true){
      const {done,value}=await reader.read(); if(done) break;
      buf+=dec.decode(value,{stream:true}); const lines=buf.split('\n'); buf=lines.pop();
      for(const line of lines){ if(!line.trim()) continue; let evt; try{evt=JSON.parse(line);}catch{continue;}
        if(evt.type==='meta'){ used=evt.model||used; route=evt.route||null; badge.textContent=used+(route?' Â· '+route:''); badge.className='badge '+(route?'badge-route':badgeCls(kind(used))); }
        else if(evt.type==='chunk'){ acc+=evt.text; msgDiv.textContent=acc; chatBox.scrollTop=chatBox.scrollHeight; }
        else if(evt.type==='error'){ acc+='\n[Hata] '+evt.message; msgDiv.textContent=acc; }
      }
    }
    conv.messages.push({role:'assistant',content:acc,model:used,route:route});
    conv.lastUsedModel=used; conv.lastRoute=route||null; conv.blink=true;
    save(); renderHistory(); renderChat();
    setTimeout(()=>{ if(conversations[currentId]){ conversations[currentId].blink=false; renderHistory(); } }, 2500);
  }catch(e){
    if(e.name!=='AbortError') conv.messages.push({role:'assistant',content:'Hata: '+e.message});
    else conv.messages.push({role:'system',content:'Uretim durduruldu.'});
    save(); renderChat();
  }finally{ pending=false; conv.pending=false; sendBtn.disabled=false; stopBtn.style.display='none'; sendBtn.textContent='Gonder'; abortCtrl=null; renderHistory(); }
}

sendBtn.onclick=sendMessage;
promptEl.addEventListener('keydown',e=>{ if(e.key==='Enter'&&!e.shiftKey){ e.preventDefault(); sendMessage(); }});
newChatBtn.onclick=createNewChat;
modelSelect.onchange=()=>{ if(conversations[currentId]){ conversations[currentId].model=modelSelect.value; updateTopBadge(conversations[currentId]); save(); } };
